describe('Accessibility - Login Fields and Product Images', () => {
  const baseUrl = 'https://www.saucedemo.com';
  const username = 'standard_user';
  const password = 'secret_sauce';

  beforeEach(() => {
    cy.visit(baseUrl);
  });

  it('should have non-empty placeholder attributes on login fields', () => {
    cy.get('[data-test="username"]')
      .should('exist')
      .should('have.attr', 'placeholder')
      .and('not.be.empty');

    cy.get('[data-test="password"]')
      .should('exist')
      .should('have.attr', 'placeholder')
      .and('not.be.empty');
  });

  it('should have non-empty alt attributes on all product images after login', () => {
    cy.get('[data-test="username"]').type(username);
    cy.get('[data-test="password"]').type(password);
    cy.get('[data-test="login-button"]').click();

    cy.url().should('include', '/inventory.html');

    cy.get('.inventory_item').should('have.length.greaterThan', 0);

    cy.get('.inventory_item img.inventory_item_img').each(($img) => {
      cy.wrap($img)
        .should('have.attr', 'alt')
        .and('not.be.empty');
    });
  });

  it('should verify all product images have descriptive alt text', () => {
    cy.get('[data-test="username"]').type(username);
    cy.get('[data-test="password"]').type(password);
    cy.get('[data-test="login-button"]').click();

    cy.get('img.inventory_item_img').then(($images) => {
      expect($images.length).to.be.greaterThan(0);

      $images.each((index, img) => {
        const altText = img.getAttribute('alt');
        expect(altText).to.exist;
        expect(altText).to.not.be.empty;
        expect(altText.length).to.be.greaterThan(0);
      });
    });
  });

  it('should handle edge case when no products are displayed', () => {
    cy.get('[data-test="username"]').type(username);
    cy.get('[data-test="password"]').type(password);
    cy.get('[data-test="login-button"]').click();

    cy.get('.inventory_item').then(($items) => {
      if ($items.length === 0) {
        cy.log('No inventory items found - edge case handled');
      } else {
        cy.get('img.inventory_item_img').each(($img) => {
          cy.wrap($img).should('have.attr', 'alt').and('not.be.empty');
        });
      }
    });
  });
});
